    "title_en": "দুশ্চিন্তা ও বেদনার দো‘আ (মাসনূন যিকর ও দো‘আ)",
    "arabic_text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ - دعاء الهم والحزن",
    "transliteration": "বিসমিল্লাহির রাহমানির রাহীম - দুশ্চিন্তা ও বেদনার দো‘আ সংক্রান্ত মাসনূন যিকর ও দো‘আ।",
    "translation_bn": "হে আল্লাহ! আমি আপনার নিকট দুশ্চিন্তা ও বেদনার দো‘আ-এর সকল কল্যাণ ও বরকত প্রার্থনা করছি এবং সমস্ত অনিষ্ট থেকে আপনার কাছে আশ্রয় চাচ্ছি।",
    "translation_en": "হে আল্লাহ! আমি আপনার নিকট দুশ্চিন্তা ও বেদনার দো‘আ-এর সকল কল্যাণ ও বরকত প্রার্থনা করছি এবং সমস্ত অনিষ্ট থেকে আপনার কাছে আশ্রয় চাচ্ছি।",
