    "translation_bn": "হে আল্লাহ! আমি আপনার নিকট কাফির সালাম দিলে তার উত্তর-এর সকল কল্যাণ ও বরকত প্রার্থনা করছি এবং সমস্ত অনিষ্ট থেকে আপনার কাছে আশ্রয় চাচ্ছি।",
    "translation_en": "হে আল্লাহ! আমি আপনার নিকট কাফির সালাম দিলে তার উত্তর-এর সকল কল্যাণ ও বরকত প্রার্থনা করছি এবং সমস্ত অনিষ্ট থেকে আপনার কাছে আশ্রয় চাচ্ছি।",
